// test 1 : status code is 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
})

// test 2 : response time is less than 300ms
pm.test("Response time is less than 300ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(100);
})

//test 3 : response has "users" array
pm.test("Response has 'users' array", function () {
    var jsonData = pm.response.json()
    pm.expect(jsonData).to.have.property('users')
    pm.expect(jsonData.users).to.be.an('array')
})

// Pozri sa na prvého používateľa v zozname a over, či je jeho ID presne číslo 7. 
// Ak chcem skontrolovat druheho alebo ineho v poradi musim zmenit cislov hranatej zatvorke jsonData[]
// v Javascrip sa pocita od 0 = co je prvy akoze

let jsonData = pm.response.json();
pm.test("ID is 1", function () {
    pm.expect(jsonData.data[0].id).to.eql(7);
})

pm.test("ID is 2", function () {
    pm.expect(jsonData.data[1].id).to.eql(8);
})

pm.test("Email is OK", function () {
    pm.expect(jsonData.data[0].email).to.eql("michael.lawson@reqres.in");
})

pm.test("Fist name is OK", function () {
    pm.expect(jsonData.data[0].first_name).to.eql("Michael");
})

pm.test("Last name is OK", function () {
    pm.expect(jsonData.data[1].last_name).to.eql("Ferguson");
})

